mapper.select:
SELECT u.id, u.username, u.nickname, u.email, u.avatar_url AS avatarUrl, u.role, u.dept_id AS deptId, d.name AS deptName, u.status, u.create_time AS createTime, u.last_login_time AS lastLoginTime FROM sys_user u LEFT JOIN sys_dept d ON u.dept_id = d.id WHERE u.is_deleted = 0
AND u.status = #{status}
AND u.role = #{role}
AND u.dept_id = #{deptId}
AND (u.username LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.create_time DESC
